const incoming = $input.first().json;
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const clean = v => typeof v === 'string' ? v.trim() : '';
const lead = {
  name: clean(body.name), email: clean(body.email).toLowerCase(),
  company: clean(body.company), website: clean(body.website),
  role: clean(body.role), need: clean(body.need), budget: clean(body.budget),
  source: clean(body.source) || 'webhook'
};
const errors = [];
for (const k of ['name','email','company','need']) if (!lead[k]) errors.push(k + ' is required');
if (lead.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) errors.push('email must be a valid email address');
if (lead.website) {
  try {
    const u = new URL(lead.website.startsWith('http') ? lead.website : 'https://' + lead.website);
    if (!['http:','https:'].includes(u.protocol)) errors.push('website must use HTTP or HTTPS');
    lead.website = u.href;
  } catch { errors.push('website must be a valid URL'); }
}
return [{json:{...lead,isValid:errors.length===0,validationError:errors.join('; '),receivedAt:new Date().toISOString()}}];

const response = $input.first().json;
const text = response.choices?.[0]?.message?.content;
if (typeof text !== 'string' || !text.trim()) throw new Error('OpenAI returned no message content; check credentials and model access.');
let ai;
try { ai = JSON.parse(text); } catch { throw new Error('OpenAI response was not valid JSON.'); }
const l = $node['Normalize and Validate Lead'].json;
const n = Number(ai.lead_score);
if (!Number.isFinite(n)) throw new Error('AI response is missing numeric lead_score.');
const score = Math.max(0,Math.min(100,Math.round(n)));
const qualification = ['high','medium','low'].includes(String(ai.qualification).toLowerCase()) ? String(ai.qualification).toLowerCase() : (score>=75?'high':score>=45?'medium':'low');
const arr = v => Array.isArray(v) ? v.map(String).slice(0,4) : [];
return [{json:{success:true,lead:{name:l.name,email:l.email,company:l.company,website:l.website,role:l.role,need:l.need,budget:l.budget,source:l.source},qualification:{lead_score:score,qualification,fit_reasons:arr(ai.fit_reasons),risks:arr(ai.risks),recommended_next_step:String(ai.recommended_next_step||''),personalized_opening_line:String(ai.personalized_opening_line||''),summary:String(ai.summary||''),confidence_note:String(ai.confidence_note||'')},receivedAt:l.receivedAt,processedAt:new Date().toISOString()}}];
